ow.Parent = poleCard\n\t\tnew("UIListLayout", {\n\t\t\tFillDirection = Enum.FillDirection.Horizontal,\n\t\t\tPadding = UDim.new(0, 4),\n\t\t\tSortOrder = Enum.SortOrder.LayoutOrder,\n\t\t\tParent = limbRow,\n\t\t})\n\n\t\tlocal limbBtns = {}\n\t\tlocal function updateLimbBtns()\n\t\t\tfor tag, b in pairs(limbBtns) do\n\t\t\t\tlocal full = limbMap[tag]\n\t\t\t\tlocal active = (_G._HaloPoleLimbs == full)\n\t\t\t\tb.BackgroundColor3 = active and Color3.fromRGB(255, 255, 255) or T.surface3\n\t\t\t\tb.TextColor3 = active and Color3.fromRGB(15, 15, 20) or T.text2\n\t\t\tend\n\t\tend\n\n\t\tfor idx, tag in ipairs(limbOptions) do\n\t\t\tlocal full = limbMap[tag]\n\t\t\tlocal b = new("TextButton", {\n\t\t\t\tSize = UDim2.new(1/#limbOptions, -4, 1, 0),\n\t\t\t\tBackgroundColor3 = (_G._HaloPoleLimbs == full) and Color3.fromRGB(255, 255, 255) or T.surface3,\n\t\t\t\tText = tag,\n\t\t\t\tTextColor3 = (_G._HaloPoleLimbs == full) and Color3.fromRGB(15, 15, 20) or T.text2,\n\t\t\t\tTextSize = 8,\n\t\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\t\tBorderSizePixel = 0,\n\t\t\t\tAutoButtonColor = false,\n\t\t\t\tLayoutOrder = idx,\n\t\t\t\tParent = limbRow,\n\t\t\t}, { corner(5) })\n\t\t\tstroke(T.line, 1, 0.4).Parent = b\n\t\t\tlimbBtns[tag] = b\n\t\t\tb.MouseButton1Click:Connect(function()\n\t\t\t\t_G._HaloPoleLimbs = full\n\t\t\t\tupdateLimbBtns()\n\t\t\tend)\n\t\tend\n\n\t\t-- Pole Length Slider (Default 14 studs, draggable and extends infinitely)\n\t\t_G._HaloPoleLength = _G._HaloPoleLength or 14\n\t\tlocal lenValLabel = new("TextLabel", {\n\t\t\tSize = UDim2.new(1, 0, 0, 14),\n\t\t\tPosition = UDim2.fromOffset(0, 66),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = string.format("Length: %d studs", math.floor(_G._HaloPoleLength)),\n\t\t\tTextColor3 = T.text2,\n\t\t\tTextSize = 8.5,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\t\tParent = poleCard,\n\t\t})\n\n\t\t-- Quick Step Increment Buttons (+10, +50, -10)\n\t\tlocal stepControls = new("Frame", {\n\t\t\tAnchorPoint = Vector2.new(1, 0),\n\t\t\tPosition = UDim2.new(1, 0, 0, 64),\n\t\t\tSize = UDim2.fromOffset(110, 18),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tParent = poleCard,\n\t\t})\n\t\tnew("UIListLayout", {\n\t\t\tFillDirection = Enum.FillDirection.Horizontal,\n\t\t\tPadding = UDim.new(0, 4),\n\t\t\tHorizontalAlignment = Enum.HorizontalAlignment.Right,\n\t\t\tParent = stepControls,\n\t\t})\n\n\t\tlocal function createStepBtn(txt, delta)\n\t\t\tlocal sb = new("TextButton", {\n\t\t\t\tSize = UDim2.fromOffset(32, 18),\n\t\t\t\tBackgroundColor3 = T.surface3,\n\t\t\t\tText = txt,\n\t\t\t\tTextColor3 = T.text1,\n\t\t\t\tTextSize = 8,\n\t\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\t\tBorderSizePixel = 0,\n\t\t\t\tAutoButtonColor = false,\n\t\t\t\tParent = stepControls,\n\t\t\t}, { corner(4) })\n\t\t\tstroke(T.line, 1, 0.4).Parent = sb\n\t\t\tsb.MouseButton1Click:Connect(function()\n\t\t\t\t_G._HaloPoleLength = math.max(1, (_G._HaloPoleLength or 14) + delta)\n\t\t\t\tlenValLabel.Text = string.format("Length: %d studs", math.floor(_G._HaloPoleLength))\n\t\t\tend)\n\t\tend\n\t\tcreateStepBtn("-10", -10)\n\t\tcreateStepBtn("+10", 10)\n\t\tcreateStepBtn("+50", 50)\n\n\t\t-- Slider Track\n\t\tlocal poleTrack = new("Frame", {\n\t\t\tSize = UDim2.new(1, 0, 0, 12),\n\t\t\tPosition = UDim2.fromOffset(0, 88),\n\t\t\tBackgroundColor3 = Color3.fromRGB(22, 22, 28),\n\t\t\tBorderSizePixel = 0,\n\t\t\tParent = poleCard,\n\t\t}, { corner(6) })\n\t\tstroke(T.line, 1, 0.35).Parent = poleTrack\n\n\t\tlocal poleInitialPct = math.clamp((_G._HaloPoleLength - 1) / 99, 0, 1)\n\t\tlocal poleProgress = new("Frame", {\n\t\t\tSize = UDim2.new(poleInitialPct, 0, 1, 0),\n\t\t\tBackgroundColor3 = Color3.fromRGB(255, 255, 255),\n\t\t\tBorderSizePixel = 0,\n\t\t\tParent = poleTrack,\n\t\t}, { corner(6) })\n\t\tnew("UIGradient", {\n\t\t\tColor = ColorSequence.new{\n\t\t\t\tColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)),\n\t\t\t\tColorSequenceKeypoint.new(1, Color3.fromRGB(195, 195, 210)),\n\t\t\t},\n\t\t\tTransparency = NumberSequence.new{\n\t\t\t\tNumberSequenceKeypoint.new(0, 0.85),\n\t\t\t\tNumberSequenceKeypoint.new(1, 0),\n\t\t\t},\n\t\t\tOffset = Vector2.new(0, 0.5),\n\t\t\tRotation = 2,\n\t\t\tParent = poleProgress,\n\t\t})\n\n\t\tlocal poleHandle = new("Frame", {\n\t\t\tSize = UDim2.fromOffset(35, 18),\n\t\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\t\tPosition = UDim2.new(poleInitialPct, (1 - 2 * poleInitialPct) * (35 / 2 - 2), 0.5, 0),\n\t\t\tBackgroundColor3 = Color3.fromRGB(255, 255, 255),\n\t\t\tBorderSizePixel = 0,\n\t\t\tZIndex = 5,\n\t\t\tParent = poleTrack,\n\t\t}, { corner(9) })\n\t\tstroke(Color3.fromRGB(255, 255, 255), 1, 0.7).Parent = poleHandle\n\t\taddHandleGlow(poleHandle)\n\n\t\tlocal poleDragging = false\n\t\tlocal function updatePoleFromInput(input)\n\t\t\tlocal absX = poleTrack.AbsolutePosition.X\n\t\t\tlocal absW = poleTrack.AbsoluteSize.X\n\t\t\tif absW <= 0 then return end\n\t\t\tlocal p = math.clamp((input.Position.X - absX) / absW, 0, 1)\n\t\t\t-- Non-linear scaling up to 100 studs via slider, can go higher indefinitely via + buttons\n\t\t\tlocal computedLen = math.floor(1 + (p * 99))\n\t\t\t_G._HaloPoleLength = computedLen\n\t\t\tglide(poleProgress, { Size = UDim2.new(p, 0, 1, 0) })\n\t\t\tglide(poleHandle, { Position = UDim2.new(p, (1 - 2 * p) * (35 / 2 - 2), 0.5, 0) })\n\t\t\tlenValLabel.Text = string.format("Length: %d studs", computedLen)\n\t\tend\n\n\t\tpoleTrack.InputBegan:Connect(function(input)\n\t\t\tif input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then\n\t\t\t\tpoleDragging = true\n\t\t\t\tupdatePoleFromInput(input)\n\t\t\tend\n\t\tend)\n\t\tuserInputService.InputChanged:Connect(function(input)\n\t\t\tif poleDragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then\n\t\t\t\tupdatePoleFromInput(input)\n\t\t\tend\n\t\tend)\n\n\t\tuserInputService.InputEnded:Connect(function(input)\n\t\t\tif input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then\n\t\t\t\tpoleDragging = false\n\t\t\tend\n\t\tend)\n\n\t\t-- Manual Direct Input Box for Infinite Length\n\t\tlocal directInputLabel = new("TextLabel", {\n\t\t\tSize = UDim2.new(0.45, 0, 0, 20),\n\t\t\tPosition = UDim2.fromOffset(0, 112),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = "Custom Length (studs):",\n\t\t\tTextColor3 = T.text3,\n\t\t\tTextSize = 8,\n\t\t\tFont = Enum.Font.BuilderSans,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\t\tParent = poleCard,\n\t\t})\n\n\t\tlocal directInputBox = new("TextBox", {\n\t\t\tAnchorPoint = Vector2.new(1, 0),\n\t\t\tPosition = UDim2.new(1, 0, 0, 110),\n\t\t\tSize = UDim2.fromOffset(72, 22),\n\t\t\tBackgroundColor3 = T.surface3,\n\t\t\tTextColor3 = T.text1,\n\t\t\tText = tostring(math.floor(_G._HaloPoleLength or 14)),\n\t\t\tTextSize = 9,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tBorderSizePixel = 0,\n\t\t\tClearTextOnFocus = false,\n\t\t\tParent = poleCard,\n\t\t}, { corner(5), pad(0, 6, 0, 6) })\n\t\tstroke(T.line, 1, 0.4).Parent = directInputBox\n\n\t\tdirectInputBox.FocusLost:Connect(function()\n\t\t\tlocal num = tonumber(directInputBox.Text)\n\t\t\tif num and num > 0 then\n\t\t\t\t_G._HaloPoleLength = num\n\t\t\t\tlenValLabel.Text = string.format("Length: %d studs", math.floor(num))\n\t\t\t\tlocal clampedP = math.clamp((num - 1) / 99, 0, 1)\n\t\t\t\tglide(poleProgress, { Size = UDim2.new(clampedP, 0, 1, 0) })\n\t\t\t\tglide(poleHandle, { Position = UDim2.new(clampedP, (1 - 2 * clampedP) * (35 / 2 - 2), 0.5, 0) })\n\t\t\telse\n\t\t\t\tdirectInputBox.Text = tostring(math.floor(_G._HaloPoleLength or 14))\n\t\t\tend\n\t\tend)\n\tend\n\n\t-- Fly Parts: fly the head (plus optional torso / arms / legs in a sit pose)\n\tcreateTrackerCard("Fly Parts", "WASD move, Space up, Ctrl down, Shift fast", false, function(st)\n\t\tif st then\n\t\t\tlocal ok, err = _G.Hal