0}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\n\t_G.combinedSequences = _G.combinedSequences or {}\n\n\tlocal draft = _G.HaloSeqDraft or { name = "", loop = false, clips = {} }\n\t_G.HaloSeqDraft = draft\n\tlocal pickerFilter = ""\n\tlocal editingIndex = nil\n\tlocal statusText, statusColor = "", nil\n\trefreshCombinePanel = nil\n\n\tlocal function fmtTime(t) return string.format("%.2fs", t) end\n\n\tfunction getAllAnimNames()\n\t\tlocal seen, out = {}, {}\n\t\tlocal function add(tbl)\n\t\t\tfor name, v in pairs(tbl or {}) do\n\t\t\t\tif type(name) == "string" and not seen[name] and not name:match("^combined:") and v ~= nil then\n\t\t\t\t\tseen[name] = true\n\t\t\t\t\ttable.insert(out, name)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\t\tadd(animationQueue); add(transformCache); add(characterAttachments)\n\t\ttable.sort(out, function(x, y) return x:lower() < y:lower() end)\n\t\treturn out\n\tend\n\n\tlocal getAvailableAnims = getAllAnimNames\n\n\tlocal function seqTotal(clips)\n\t\tlocal t = 0\n\t\tfor _, c in ipairs(clips) do\n\t\t\tt = t + math.max(0, ((c.stop or 0) - (c.start or 0)) / math.max(0.05, math.abs(c.speed or 1)))\n\t\tend\n\t\treturn t\n\tend\n\n\tlocal function setStatus(txt, col)\n\t\tstatusText, statusColor = txt or "", col\n\tend\n\n\tlocal function makeBtn(parent, text, size, pos, bg, fg, strokeCol)\n\t\tlocal b = new("TextButton", {\n\t\t\tSize = size, Position = pos or UDim2.new(),\n\t\t\tBackgroundColor3 = bg or T.surface3,\n\t\t\tText = text, TextColor3 = fg or T.text1, TextSize = 9,\n\t\t\tFont = Enum.Font.BuilderSansBold, BorderSizePixel = 0, AutoButtonColor = false,\n\t\t\tZIndex = 8, Parent = parent,\n\t\t}, { corner(5) })\n\t\tstroke(strokeCol or T.line, 1, 0.5).Parent = b\n\t\treturn b\n\tend\n\n\tlocal function makeBox(parent, text, size, pos, placeholder)\n\t\tlocal tb = new("TextBox", {\n\t\t\tSize = size, Position = pos,\n\t\t\tBackgroundColor3 = T.surface,\n\t\t\tText = text, PlaceholderText = placeholder or "",\n\t\t\tPlaceholderColor3 = T.text3, TextColor3 = T.text1, TextSize = 9,\n\t\t\tFont = Enum.Font.BuilderSansMedium, ClearTextOnFocus = false,\n\t\t\tBorderSizePixel = 0, ZIndex = 8, Parent = parent,\n\t\t}, { corner(5), pad(0, 4, 0, 4) })\n\t\tstroke(T.line, 1, 0.5).Parent = tb\n\t\treturn tb\n\tend\n\n\tlocal function card(order)\n\t\tlocal c = new("Frame", {\n\t\t\tSize = UDim2.new(1, 0, 0, 0),\n\t\t\tAutomaticSize = Enum.AutomaticSize.Y,\n\t\t\tBackgroundColor3 = T.surface2, BackgroundTransparency = 0.35,\n\t\t\tBorderSizePixel = 0, ZIndex = 7, LayoutOrder = order, Parent = combinePanelFrame,\n\t\t}, { corner(8), pad(8, 10, 10, 10) })\n\t\tstroke(T.line, 1, 0.4).Parent = c\n\t\tnew("UIListLayout", { Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder, Parent = c })\n\t\treturn c\n\tend\n\n\tlocal function iconBtn(parent, image, size, pos, tint, bg)\n\t\tlocal b = new("ImageButton", {\n\t\t\tSize = size, Position = pos or UDim2.new(),\n\t\t\tBackgroundColor3 = bg or T.surface,\n\t\t\tBackgroundTransparency = bg == false and 1 or 0,\n\t\t\tAutoButtonColor = false, BorderSizePixel = 0, Image = "", ZIndex = 9, Parent = parent,\n\t\t}, { corner(5) })\n\t\tstroke(T.line, 1, 0.55).Parent = b\n\t\tnew("ImageLabel", {\n\t\t\tAnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),\n\t\t\tSize = UDim2.fromOffset(12, 12), BackgroundTransparency = 1,\n\t\t\tImage = image, ImageColor3 = tint or T.text2, ZIndex = 10, Parent = b,\n\t\t})\n\t\treturn b\n\tend\n\n\tlocal function rowFrame(parent, height, order)\n\t\treturn new("Frame", {\n\t\t\tSize = UDim2.new(1, 0, 0, height), BackgroundTransparency = 1,\n\t\t\tLayoutOrder = order, ZIndex = 8, Parent = parent,\n\t\t})\n\tend\n\n\tlocal function label(parent, text, size, pos, ts, col, font, align)\n\t\treturn new("TextLabel", {\n\t\t\tSize = size, Position = pos or UDim2.new(), BackgroundTransparency = 1,\n\t\t\tText = text, TextColor3 = col or T.text1, TextSize = ts or 10,\n\t\t\tFont = font or Enum.Font.BuilderSansBold,\n\t\t\tTextXAlignment = align or Enum.TextXAlignment.Left,\n\t\t\tTextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 8, Parent = parent,\n\t\t})\n\tend\n\n\tlocal function sectionLabel(parent, text, order)\n\t\tlocal l = label(parent, string.upper(text), UDim2.new(1, 0, 0, 12), nil, 8, T.text3, Enum.Font.BuilderSansBold)\n\t\tl.LayoutOrder = order\n\t\treturn l\n\tend\n\n\tlocal function listenForKey(btn, onKey)\n\t\tif isSettingBind then return end\n\t\tisSettingBind = true\n\t\tbtn.Text = "..."\n\t\tlocal conn\n\t\tconn = userInputService.InputBegan:Connect(function(input)\n\t\t\tif input.UserInputType ~= Enum.UserInputType.Keyboard then return end\n\t\t\tconn:Disconnect()\n\t\t\ttask.defer(function() isSettingBind = false end)\n\t\t\tif input.KeyCode == Enum.KeyCode.Escape or input.KeyCode == Enum.KeyCode.Backspace then\n\t\t\t\tonKey(nil)\n\t\t\telse\n\t\t\t\tonKey(input.KeyCode)\n\t\t\tend\n\t\tend)\n\t\ttask.delay(8, function()\n\t\t\tif conn and conn.Connected then\n\t\t\t\tconn:Disconnect()\n\t\t\t\tisSettingBind = false\n\t\t\t\tonKey(false)\n\t\t\tend\n\t\tend)\n\tend\n\n\tlocal function previewDraft()\n\t\tlocal st = _G.HaloSeqState\n\t\tif st.playing and st.seq == draft then\n\t\t\t_G.stopCombinedSequence()\n\t\t\treturn\n\t\tend\n\t\tlocal ok, err = _G.playCombinedSequence(draft)\n\t\tif not ok then setStatus(err, T.danger) else setStatus("Previewing sequence...", T.accent) end\n\t\trefreshCombinePanel()\n\tend\n\n\tlocal function saveDraft()\n\t\tif #draft.clips == 0 then setStatus("Add at least one animation first", T.danger); refreshCombinePanel(); return end\n\t\tlocal name = (draft.name or ""):match("^%s*(.-)%s*$")\n\t\tif name == "" then name = "Sequence " .. (#_G.combinedSequences + 1) end\n\t\tlocal clips = {}\n\t\tfor _, c in ipairs(draft.clips) do\n\t\t\ttable.insert(clips, { anim = c.anim, start = c.start, stop = c.stop, speed = c.speed })\n\t\tend\n\t\tif editingIndex and _G.combinedSequences[editingIndex] then\n\t\t\tlocal seq = _G.combinedSequences[editingIndex]\n\t\t\tseq.name, seq.clips, seq.loop = name, clips, draft.loop\n\t\telse\n\t\t\ttable.insert(_G.combinedSequences, { name = name, loop = draft.loop, clips = clips })\n\t\tend\n\t\tpcall(saveCombinedSequences)\n\t\tdraft.name, draft.clips, draft.loop = "", {}, false\n\t\teditingIndex = nil\n\t\tsetStatus("Saved \\"" .. name .. "\\" - bind a key below", Color3.fromRGB(80, 220, 120))\n\t\trefreshCombinePanel()\n\tend\n\n\trefreshCombinePanel = function()\n\t\tfor _, child in ipairs(combinePanelFrame:GetChildren()) do\n\t\t\tif child:IsA("GuiObject") then child:Destroy() end\n\t\tend\n\t\tlocal st = _G.HaloSeqState\n\n\t\t-- \u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500} Builder card \u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\n\t\tlocal builder = card(1)\n\t\tlocal order = 0\n\t\tlocal function nextOrder() order = order + 1; return order end\n\n\t\tlocal head = rowFrame(builder, 16, nextOrder())\n\t\tlabel(head, editingIndex and "Editing Sequence" or "Sequence Builder", UDim2.new(0.6, 0, 1, 0), nil, 11)\n\t\tlabel(head, "Total " .. fmtTime(seqTotal(draft.clips)), UDim2.new(0.4, 0, 1, 0), UDim2.new(0.6, 0, 0, 0), 9.5, T.accent2, nil, Enum.TextXAlignment.Right)\n\n\t\tlocal nameRow = rowFrame(builder, 22, nextOrder())\n\t\tlocal nameBox = makeBox(nameRow, draft.name or "", UDim2.new(1, -68, 1, 0), UDim2.new(), "Sequence name")\n\t\tnameBox.FocusLost:Connect(function() draft.name = nameBox.Text end)\n\t\tlocal loopBtn = makeBtn(nameRow, draft.loop and "Loop: ON" or "Loop: OFF", UDim2.fromOffset(62, 22), UDim2.new(1, -62, 0, 0),\n\t\t\tdraft.loop and Color3.fromRGB(255, 255, 255) or T.surface3, draft.loop and Color3.fromRGB(15, 15, 20) or T.text2)\n\t\tloopBtn.MouseButton1Click:Connect(function()\n\t\t\tdraft.name = nameBox.Text\n\t\t\tdraft.loop = not draft.loop\n\t\t\trefreshCombinePanel()\n\t\tend)\n\n\t\tsectionLabel(builder, "Add animation  -  all + customs", nextOrder())\n\t\tlocal searchRow = rowFrame(builder, 22, nextOrder())\n\t\tlocal search = makeBox(searchRow, pickerFilter, UDim2.new(1, 0, 1, 0), UDim2.new(), "Search all animations...")\n\t\tlocal list = new("ScrollingFrame", {\n\t\t\tSize = UDim2.new(1, 0, 0, 110), LayoutOrder = nextOrder(),\n\t\t\tBackgroundColor3 = T.surface, BackgroundTransparency = 0.4, BorderSizePixel = 0,\n\t\t\tScrollBarThickness = 0, AutomaticCanvasSize = Enum.AutomaticSize.Y, CanvasSize = UDim2.new(),\n\t\t\tZIndex = 8, Parent = builder,\n\t\t}, { corner(6), pad(3, 3, 3, 3) })\n\t\tnew("UIListLayout", { Padding = UDim.new(0, 2), SortOrder = Enum.SortOrder.LayoutOrder, Parent = list })\n\t\tlocal function fillList()\n\t\t\tfor _, c in ipairs(list:GetChildren()) do\n\t\t\t\tif c:IsA("GuiObject") then c:Destroy() end\n\t\t\tend\n\t\t\tlocal f = pickerFilter:lower()\n\t\t\tlocal shown = 0\n\t\t\tfor _, name in ipairs(getAllAnimNames()) do\n\t\t\t\tif f == "" or name:lower():find(f, 1, true) then\n\t\t\t\t\tshown = shown + 1\n\t\t\t\t\tif shown > 150 then break end\n\t\t\t\t\tlocal row = new("TextButton", {\n\t\t\t\t\t\tSize = UDim2.new(1, 0, 0, 26), LayoutOrder = shown,\n\t\t\t\t\t\tBackgroundColor3 = T.surface2, BackgroundTransparency = 0.25,\n\t\t\t\t\t\tText = (name:sub(-4):lower() == ".lua") and name:sub(1, -5) or name,\n\t\t\t\t\t\tTextColor3 = T.text1, TextSize = 10, Font = Enum.Font.BuilderSansMedium,\n\t\t\t\t\t\tTextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,\n\t\t\t\t\t\tAutoButtonColor = false, BorderSizePixel = 0, ZIndex = 9, Parent = list,\n\t\t\t\t\t}, { corner(6), pad(0, 26, 0, 9) })\n\t\t\t\t\tnew("TextLabel", {\n\t\t\t\t\t\tAnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 20, 0.5, 0),\n\t\t\t\t\t\tSize = UDim2.fromOffset(14, 14), BackgroundTransparency = 1,\n\t\t\t\t\t\tText = "+", TextColor3 = T.text3, TextSize = 14, Font = Enum.Font.BuilderSansBold, ZIndex = 10, Parent = row,\n\t\t\t\t\t})\n\t\t\t\t\trow.MouseButton1Click:Connect(function()\n\t\t\t\t\t\tdraft.name = nameBox.Text\n\t\t\t\t\t\ttable.insert(draft.clips, { anim = name, start = 0, stop = _G.HaloSeqDuration(name), speed = 1 })\n\t\t\t\t\t\tsetStatus("Added " .. name, T.text2)\n\t\t\t\t\t\trefreshCombinePanel()\n\t\t\t\t\tend)\n\t\t\t\tend\n\t\t\tend\n\t\t\tif shown == 0 then\n\t\t\t\tlocal e = label(list, "No animations found", UDim2.new(1, 0, 0, 22), nil, 9, T.text3, Enum.Font.BuilderSans, Enum.TextXAlignment.Center)\n\t\t\t\te.LayoutOrder = 1\n\t\t\tend\n\t\tend\n\t\tfillList()\n\t\tsearch:GetPropertyChangedSignal("Text"):Connect(function()\n\t\t\tpickerFilter = search.Text\n\t\t\tfillList()\n\t\tend)\n\n\t\tsectionLabel(builder, "Sequence  -  trim and speed per clip", nextOrder())\n\t\tlocal clipsBox = new("Frame", {\n\t\t\tSize = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,\n\t\t\tBackgroundTransparency = 1, LayoutOrder = nextOrder(), ZIndex = 8, Parent = builder,\n\t\t})\n\t\tnew("UIListLayout", { Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder, Parent = clipsBox })\n\t\tif #draft.clips == 0 then\n\t\t\tlocal e = label(clipsBox, "Pick animations above to build your sequence", UDim2.new(1, 0, 0, 24), nil, 9, T.text3, Enum.Font.BuilderSans, Enum.TextXAlignment.Center)\n\t\t\te.LayoutOrder = 1\n\t\tend\n\t\tfor i, clip in ipairs(draft.clips) do\n\t\t\tlocal row = new("Frame", {\n\t\t\t\tSize = UDim2.new(1, 0, 0, 74), LayoutOrder = i,\n\t\t\t\tBackgroundColor3 = T.surface3, BackgroundTransparency = 0.35, BorderSizePixel = 0,\n\t\t\t\tZIndex = 8, Parent = clipsBox,\n\t\t\t}, { corner(8), pad(7, 8, 7, 8) })\n\t\t\tstroke(T.line, 1, 0.5).Parent = row\n\t\t\tlocal active = st.playing and st.seq == draft and st.index == i\n\t\t\tlocal shownName = (clip.anim:sub(-4):lower() == ".lua") and clip.anim:sub(1, -5) or clip.anim\n\t\t\tlocal badge = new("TextLabel", {\n\t\t\t\tSize = UDim2.fromOffset(18, 18), BackgroundColor3 = active and Color3.fromRGB(255, 255, 255) or T.surface,\n\t\t\t\tText = tostring(i), TextColor3 = active and Color3.fromRGB(15, 15, 20) or T.text2,\n\t\t\t\tTextSize = 9, Font = Enum.Font.BuilderSansBold, BorderSizePixel = 0, ZIndex = 9, Parent = row,\n\t\t\t}, { corner(9) })\n\t\t\tlabel(row, shownName, UDim2.new(1, -92, 0, 18), UDim2.fromOffset(25, 0), 10, active and T.accent or T.text1, Enum.Font.BuilderSansMedium)\n\t\t\tlocal up = iconBtn(row, upIconId, UDim2.fromOffset(20, 18), UDim2.new(1, -66, 0, 0))\n\t\t\tlocal dn = iconBtn(row, downIconId, UDim2.fromOffset(20, 18), UDim2.new(1, -44, 0, 0))\n\t\t\tlocal rm = iconBtn(row, delIconId, UDim2.fromOffset(20, 18), UDim2.new(1, -22, 0, 0), T.danger, Color3.fromRGB(38, 20, 24))\n\t\t\tup.MouseButton1Click:Connect(function()\n\t\t\t\tif i > 1 then draft.clips[i], draft.clips[i - 1] = draft.clips[i - 1], draft.clips[i]; draft.name = nameBox.Text; refreshCombinePanel() end\n\t\t\tend)\n\t\t\tdn.MouseButton1Click:Connect(function()\n\t\t\t\tif i < #draft.clips then draft.clips[i], draft.clips[i + 1] = draft.clips[i + 1], draft.clips[i]; draft.name = nameBox.Text; refreshCombinePanel() end\n\t\t\tend)\n\t\t\trm.MouseButton1Click:Connect(function()\n\t\t\t\ttable.remove(draft.clips, i); draft.name = nameBox.Text; refreshCombinePanel()\n\t\t\tend)\n\t\t\tlocal dur = _G.HaloSeqDuration(clip.anim)\n\t\t\tlocal function field(title, x, value, commit)\n\t\t\t\tlabel(row, title, UDim2.new(0.32, 0, 0, 10), UDim2.new(x, 0, 0, 22), 7.5, T.text3, Enum.Font.BuilderSansMedium)\n\t\t\t\tlocal tb = makeBox(row, value, UDim2.new(0.32, -4, 0, 20), UDim2.new(x, 0, 0, 33))\n\t\t\t\ttb.TextXAlignment = Enum.TextXAlignment.Center\n\t\t\t\ttb.FocusLost:Connect(function()\n\t\t\t\t\tlocal n = tonumber(tb.Text)\n\t\t\t\t\tif n then commit(n) end\n\t\t\t\t\trefreshCombinePanel()\n\t\t\t\tend)\n\t\t\tend\n\t\t\tfield("START (s)", 0, string.format("%.2f", clip.start), function(n)\n\t\t\t\tclip.start = math.clamp(n, 0, math.max(0, clip.stop - 0.05))\n\t\t\tend)\n\t\t\tfield("END (s)  /" .. string.format("%.1f", dur), 0.34, string.format("%.2f", clip.stop), function(n)\n\t\t\t\tclip.stop = math.clamp(n, clip.start + 0.05, math.max(dur, clip.start + 0.05))\n\t\t\tend)\n\t\t\tfield("SPEED (x)", 0.68, string.format("%.2f", clip.speed), function(n)\n\t\t\t\tclip.speed = math.clamp(n, 0.1, 5)\n\t\t\tend)\n\t\t\t-- mini timeline: bright part = the portion of the animation that plays\n\t\t\tlocal track = new("Frame", {\n\t\t\t\tSize = UDim2.new(1, 0, 0, 3), Position = UDim2.new(0, 0, 1, -3),\n\t\t\t\tBackgroundColor3 = T.surface, BorderSizePixel = 0, ZIndex = 9, Parent = row,\n\t\t\t}, { corner(2) })\n\t\t\tlocal f0 = math.clamp(clip.start / math.max(dur, 0.01), 0, 1)\n\t\t\tlocal f1 = math.clamp(clip.stop / math.max(dur, 0.01), f0, 1)\n\t\t\tnew("Frame", {\n\t\t\t\tPosition = UDim2.fromScale(f0, 0), Size = UDim2.fromScale(math.max(f1 - f0, 0.01), 1),\n\t\t\t\tBackgroundColor3 = Color3.fromRGB(255, 255, 255), BorderSizePixel = 0, ZIndex = 10, Parent = track,\n\t\t\t}, { corner(2) })\n\t\tend\n\n\t\tlocal act = rowFrame(builder, 24, nextOrder())\n\t\tnew("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder, Parent = act })\n\t\tlocal playing = st.playing and st.seq == draft\n\t\tlocal prev = makeBtn(act, playing and "Stop" or "Preview", UDim2.new(0.34, -3, 1, 0), nil,\n\t\t\tplaying and Color3.fromRGB(40, 40, 45) or T.surface3, T.accent2, T.accent2)\n\t\tprev.LayoutOrder = 1\n\t\tlocal save = makeBtn(act, editingIndex and "Update" or "Save", UDim2.new(0.34, -3, 1, 0), nil,\n\t\t\tColor3.fromRGB(255, 255, 255), Color3.fromRGB(15, 15, 20))\n\t\tsave.LayoutOrder = 2\n\t\tlocal clr = makeBtn(act, editingIndex and "Cancel" or "Clear", UDim2.new(0.32, -2, 1, 0), nil, T.surface3, T.danger, T.danger)\n\t\tclr.LayoutOrder = 3\n\t\tprev.MouseButton1Click:Connect(function() draft.name = nameBox.Text; previewDraft() end)\n\t\tsave.MouseButton1Click:Connect(function() draft.name = nameBox.Text; saveDraft() end)\n\t\tclr.MouseButton1Click:Connect(function()\n\t\t\tif st.playing and st.seq == draft then _G.stopCombinedSequence() end\n\t\t\tdraft.name, draft.clips, draft.loop = "", {}, false\n\t\t\teditingIndex = nil\n\t\t\tsetStatus("", nil)\n\t\t\trefreshCombinePanel()\n\t\tend)\n\t\tlocal stLbl = label(builder, statusText, UDim2.new(1, 0, 0, 14), nil, 8.5, statusColor or T.text3, Enum.Font.BuilderSans)\n\t\tstLbl.LayoutOrder = nextOrder()\n\n\t\t-- \u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500} Saved sequences \u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\n\t\tlocal seqs = _G.combinedSequences\n\t\tlocal saved = card(2)\n\t\tlocal h = label(saved, "Saved Sequences", UDim2.new(1, 0, 0, 16), nil, 11.5)\n\t\th.LayoutOrder = 1\n\t\tif #seqs == 0 then\n\t\t\tlocal e = label(saved, "Nothing saved yet", UDim2.new(1, 0, 0, 22), nil, 9, T.text3, Enum.Font.BuilderSans, Enum.TextXAlignment.Center)\n\t\t\te.LayoutOrder = 2\n\t\tend\n\t\tfor idx, seq in ipairs(seqs) do\n\t\t\tlocal isPlaying = st.playing and st.seq == seq\n\t\t\tlocal row = new("Frame", {\n\t\t\t\tSize = UDim2.new(1, 0, 0, 64), LayoutOrder = 1 + idx,\n\t\t\t\tBackgroundColor3 = T.surface3, BackgroundTransparency = 0.3, BorderSizePixel = 0,\n\t\t\t\tZIndex = 8, Parent = saved,\n\t\t\t}, { corner(6), pad(6, 8, 6, 8) })\n\t\t\tstroke(T.line, 1, 0.5).Parent = row\n\t\t\tlabel(row, seq.name, UDim2.new(1, 0, 0, 14), UDim2.fromOffset(0, 0), 10, isPlaying and T.accent or T.text1)\n\t\t\tlabel(row, string.format("%d clips - %s%s", #seq.clips, fmtTime(seqTotal(seq.clips)), seq.loop and " - loop" or ""),\n\t\t\t\tUDim2.new(1, 0, 0, 11), UDim2.fromOffset(0, 15), 8, T.text3, Enum.Font.BuilderSans)\n\t\t\tlocal btns = new("Frame", {\n\t\t\t\tSize = UDim2.new(1, 0, 0, 22), Position = UDim2.new(0, 0, 1, -22),\n\t\t\t\tBackgroundTransparency = 1, ZIndex = 8, Parent = row,\n\t\t\t})\n\t\t\tnew("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder, Parent = btns })\n\t\t\tlocal play = makeBtn(btns, isPlaying and "Stop" or "Play", UDim2.new(0.22, -3, 1, 0), nil,\n\t\t\t\tisPlaying and Color3.fromRGB(40, 40, 45) or Color3.fromRGB(255, 255, 255), isPlaying and T.text1 or Color3.fromRGB(15, 15, 20))\n\t\t\tplay.LayoutOrder = 1\n\t\t\tlocal keyBtn = makeBtn(btns, seq.key and seq.key.Name or "Bind key", UDim2.new(0.3, -3, 1, 0), nil,\n\t\t\t\tT.surface, seq.key and T.accent or T.text2)\n\t\t\tkeyBtn.LayoutOrder = 2\n\t\t\tlocal edit = makeBtn(btns, "Edit", UDim2.new(0.22, -3, 1, 0))\n\t\t\tedit.LayoutOrder = 3\n\t\t\tlocal del = iconBtn(btns, delIconId, UDim2.new(0.26, -3, 1, 0), nil, T.danger, Color3.fromRGB(38, 20, 24))\n\t\t\tdel.LayoutOrder = 4\n\t\t\tplay.MouseButton1Click:Connect(function()\n\t\t\t\tif isPlaying then\n\t\t\t\t\t_G.stopCombinedSequence()\n\t\t\t\telse\n\t\t\t\t\tlocal ok, err = _G.playCombinedSequence(seq)\n\t\t\t\t\tsetStatus(ok and "" or err, ok and nil or T.danger)\n\t\t\t\tend\n\t\t\t\trefreshCombinePanel()\n\t\t\tend)\n\t\t\tkeyBtn.MouseButton1Click:Connect(function()\n\t\t\t\tlistenForKey(keyBtn, function(k)\n\t\t\t\t\tif k == false then refreshCombinePanel(); return end\n\t\t\t\t\tif k then\n\t\t\t\t\t\tfor _, other in ipairs(_G.combinedSequences) do\n\t\t\t\t\t\t\tif other ~= seq and other.key == k then other.key = nil end\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\t\tseq.key = k\n\t\t\t\t\tpcall(saveCombinedSequences)\n\t\t\t\t\trefreshCombinePanel()\n\t\t\t\tend)\n\t\t\tend)\n\t\t\tedit.MouseButton1Click:Connect(function()\n\t\t\t\tdraft.name, draft.loop, draft.clips = seq.name, seq.loop == true, {}\n\t\t\t\tfor _, c in ipairs(seq.clips) do\n\t\t\t\t\ttable.insert(draft.clips, { anim = c.anim, start = c.start, stop = c.stop, speed = c.speed })\n\t\t\t\tend\n\t\t\t\teditingIndex = idx\n\t\t\t\tsetStatus("Editing \\"" .. seq.name .. "\\"", T.text2)\n\t\t\t\trefreshCombinePanel()\n\t\t\tend)\n\t\t\tdel.MouseButton1Click:Connect(function()\n\t\t\t\tif st.playing and st.seq == seq then _G.stopCombinedSequence() end\n\t\t\t\ttable.remove(_G.combinedSequences, idx)\n\t\t\t\tif editingIndex == idx then editingIndex = nil end\n\t\t\t\tpcall(saveCombinedSequences)\n\t\t\t\trefreshCombinePanel()\n\t\t\tend)\n\t\tend\n\tend\n\n\t-- keep the panel in sync as the sequence advances / ends (only while visible)\n\tlocal lastSeqSig = ""\n\t_G.HaloSeqOnChange = function()\n\t\ttask.defer(function()\n\t\t\tif combinePanelFrame and combinePanelFrame.Parent and combinePanelFrame.Visible then\n\t\t\t\tlocal st = _G.HaloSeqState\n\t\t\t\tlocal sig = tostring(st.playing) .. tostring(st.index) .. tostring(st.seq)\n\t\t\t\tif sig ~= lastSeqSig then\n\t\t\t\t\tlastSeqSig = sig\n\t\t\t\t\tif not userInputService:GetFocusedTextBox() then\n\t\t\t\t\t\tpcall(refreshCombinePanel)\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\tend)\n\tend\n\tpcall(loadCombinedSequences)\n\trefreshCombinePanel()\n\n\tend\n\tdo\n\t-- \u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\n\t-- RECORD TAB: SELF PLAYER ANIMATION RECORDER\n\t-- \u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\n\tlocal isRecordingAnim = false\n\tlocal recordedFrames = {}\n\tlocal recordStartTime = 0\n\tlocal recordLoopConn = nil\n\tlocal recordStatusLabel\n\tlocal recordTimerLabel\n\tlocal recToggleBtn\n\tlocal recSaveBtn\n\tlocal recPrevBtn\n\tlocal recNameInput\n\n\tlocal function getTargetRecordingCharacter()\n\t\tlocal clone = (onyxAPI and onyxAPI.get_clone) and onyxAPI.get_clone(localPlayer)\n\t\tif clone and clone:FindFirstChild("HumanoidRootPart") then\n\t\t\treturn clone\n\t\tend\n\t\tif localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart") then\n\t\t\treturn localPlayer.Character\n\t\tend\n\t\treturn nil\n\tend\n\n\tlocal function captureFramePose(targetChar)\n\t\tif not targetChar then return nil end\n\t\tlocal frameData = {}\n\t\tlocal joints = {}\n\n\t\tfor _, desc in ipairs(targetChar:GetDescendants()) do\n\t\t\tif desc:IsA("Motor6D") and desc.Enabled and desc.Part0 and desc.Part1 then\n\t\t\t\tlocal p1Name = desc.Part1.Name\n\t\t\t\tif p1Name ~= "HumanoidRootPart" then\n\t\t\t\t\tlocal cf = desc.Transform or CFrame.identity\n\t\t\t\t\tframeData[p1Name] = cf\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\n\t\tif next(frameData) == nil then\n\t\t\tlocal hrp = targetChar:FindFirstChild("HumanoidRootPart")\n\t\t\tif hrp then\n\t\t\t\tfor _, pName in ipairs({"Head", "Torso", "UpperTorso", "LowerTorso", "Right Arm", "Left Arm", "Right Leg", "Left Leg", "RightUpperArm", "LeftUpperArm", "RightLowerArm", "LeftLowerArm", "RightHand", "LeftHand", "RightUpperLeg", "LeftUpperLeg", "RightLowerLeg", "LeftLowerLeg", "RightFoot", "LeftFoot"}) do\n\t\t\t\t\tlocal part = targetChar:FindFirstChild(pName)\n\t\t\t\t\tif part and part:IsA("BasePart") then\n\t\t\t\t\t\tframeData[pName] = hrp.CFrame:ToObjectSpace(part.CFrame)\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\n\t\treturn frameData\n\tend\n\n\tlocal function buildRecordedLua(frames)\n\t\tlocal lines = { "return {" }\n\t\tfor _, kf in ipairs(frames) do\n\t\t\ttable.insert(lines, "        {")\n\t\t\ttable.insert(lines, string.format("            Time = %.4f,", kf.Time))\n\t\t\ttable.insert(lines, "            Data = {")\n\t\t\tfor partName, cf in pairs(kf.Data) do\n\t\t\t\tlocal x, y, z, R00, R01, R02, R10, R11, R12, R20, R21, R22 = cf:GetComponents()\n\t\t\t\tlocal cfStr = string.format("CFrame.new(%.4f, %.4f, %.4f, %.4f, %.4f, %.4f, %.4f, %.4f, %.4f, %.4f, %.4f, %.4f)",\n\t\t\t\t\tx, y, z, R00, R01, R02, R10, R11, R12, R20, R21, R22)\n\t\t\t\ttable.insert(lines, string.format("                [\\"%s\\"] = %s,", partName, cfStr))\n\t\t\tend\n\t\t\ttable.insert(lines, "            }")\n\t\t\ttable.insert(lines, "        },")\n\t\tend\n\t\ttable.insert(lines, "}")\n\t\treturn table.concat(lines, "\\n")\n\tend\n\n\tlocal function stopRecordingAnim()\n\t\tif not isRecordingAnim then return end\n\t\tisRecordingAnim = false\n\t\tif recordLoopConn then\n\t\t\trecordLoopConn:Disconnect()\n\t\t\trecordLoopConn = nil\n\t\tend\n\t\tlocal duration = tick() - recordStartTime\n\t\tif recordStatusLabel then\n\t\t\trecordStatusLabel.Text = string.format("Recorded %d keyframes (%.2fs)", #recordedFrames, duration)\n\t\t\trecordStatusLabel.TextColor3 = T.text1\n\t\tend\n\t\tif recToggleBtn then\n\t\t\trecToggleBtn.Text = "\u{25cf} Record"\n\t\t\trecToggleBtn.BackgroundColor3 = Color3.fromRGB(220, 50, 60)\n\t\tend\n\t\tif recSaveBtn then\n\t\t\trecSaveBtn.Visible = (#recordedFrames > 0)\n\t\tend\n\t\tif recPrevBtn then\n\t\t\trecPrevBtn.Visible = (#recordedFrames > 0)\n\t\tend\n\tend\n\n\tlocal function startRecordingAnim()\n\t\tif isRecordingAnim then return end\n\t\tlocal targetChar = getTargetRecordingCharacter()\n\t\tif not targetChar then\n\t\t\tif recordStatusLabel then\n\t\t\t\trecordStatusLabel.Text = "Error: Character not found!"\n\t\t\t\trecordStatusLabel.TextColor3 = T.danger\n\t\t\tend\n\t\t\treturn\n\t\tend\n\n\t\trecordedFrames = {}\n\t\trecordStartTime = tick()\n\t\tisRecordingAnim = true\n\n\t\tif recToggleBtn then\n\t\t\trecToggleBtn.Text = "\u{25a0} Stop Recording"\n\t\t\trecToggleBtn.BackgroundColor3 = Color3.fromRGB(40, 40, 45)\n\t\tend\n\t\tif recordStatusLabel then\n\t\t\trecordStatusLabel.Text = "Recording player pose @ 30 FPS..."\n\t\t\trecordStatusLabel.TextColor3 = T.accent\n\t\tend\n\t\tif recSaveBtn then recSaveBtn.Visible = false end\n\t\tif recPrevBtn then recPrevBtn.Visible = false end\n\n\t\tlocal lastSample = 0\n\t\tlocal sampleInterval = 1 / 30\n\n\t\trecordLoopConn = runService.Heartbeat:Connect(function()\n\t\t\tLPS_ATTRIBUTES(VM(NONE))\n\t\t\tif not isRecordingAnim then return end\n\t\t\tlocal now = tick()\n\t\t\tlocal elapsed = now - recordStartTime\n\t\t\tif recordTimerLabel then\n\t\t\t\trecordTimerLabel.Text = string.format("%02d:%04.1f", math.floor(elapsed / 60), elapsed % 60)\n\t\t\tend\n\t\t\tif (now - lastSample) >= sampleInterval then\n\t\t\t\tlastSample = now\n\t\t\t\tlocal char = getTargetRecordingCharacter()\n\t\t\t\tif char then\n\t\t\t\t\tlocal data = captureFramePose(char)\n\t\t\t\t\tif data and next(data) ~= nil then\n\t\t\t\t\t\ttable.insert(recordedFrames, {\n\t\t\t\t\t\t\tTime = elapsed,\n\t\t\t\t\t\t\tData = data\n\t\t\t\t\t\t})\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\tend)\n\tend\n\n\tlocal function refreshRecordPanel()\n\t\tfor _, child in ipairs(recordPanelFrame:GetChildren()) do\n\t\t\tif child:IsA("GuiObject") and not child:IsA("UIListLayout") and not child:IsA("UIPadding") then\n\t\t\t\tchild:Destroy()\n\t\t\tend\n\t\tend\n\n\t\tlocal card = new("Frame", {\n\t\t\tSize = UDim2.new(1, 0, 0, 236),\n\t\t\tBackgroundColor3 = T.surface2,\n\t\t\tBackgroundTransparency = 0.35,\n\t\t\tBorderSizePixel = 0,\n\t\t\tParent = recordPanelFrame,\n\t\t}, { corner(8), pad(0, 12, 0, 12) })\n\t\tstroke(T.line, 1, 0.4).Parent = card\n\n\t\tnew("TextLabel", {\n\t\t\tSize = UDim2.new(1, 0, 0, 18),\n\t\t\tPosition = UDim2.fromOffset(0, 10),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = "Animation Recorder",\n\t\t\tTextColor3 = T.text1,\n\t\t\tTextSize = 12,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\t\tParent = card,\n\t\t})\n\n\t\tnew("TextLabel", {\n\t\t\tSize = UDim2.new(1, 0, 0, 14),\n\t\t\tPosition = UDim2.fromOffset(0, 30),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = "Record your pose, preview it, save to customs",\n\t\t\tTextColor3 = T.text3,\n\t\t\tTextSize = 8.5,\n\t\t\tFont = Enum.Font.BuilderSans,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\t\tParent = card,\n\t\t})\n\n\t\trecordTimerLabel = new("TextLabel", {\n\t\t\tSize = UDim2.new(1, 0, 0, 36),\n\t\t\tPosition = UDim2.fromOffset(0, 52),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = "00:00.0",\n\t\t\tTextColor3 = T.text1,\n\t\t\tTextSize = 24,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Center,\n\t\t\tParent = card,\n\t\t})\n\n\t\trecordStatusLabel = new("TextLabel", {\n\t\t\tSize = UDim2.new(1, 0, 0, 16),\n\t\t\tPosition = UDim2.fromOffset(0, 92),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = "Ready to record",\n\t\t\tTextColor3 = T.text2,\n\t\t\tTextSize = 9.5,\n\t\t\tFont = Enum.Font.BuilderSansMedium,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Center,\n\t\t\tParent = card,\n\t\t})\n\n\t\trecToggleBtn = new("TextButton", {\n\t\t\tSize = UDim2.new(1, 0, 0, 32),\n\t\t\tPosition = UDim2.new(0, 0, 0, 114),\n\t\t\tBackgroundColor3 = Color3.fromRGB(220, 50, 60),\n\t\t\tText = isRecordingAnim and "\u{25a0} Stop Recording" or "\u{25cf} Record",\n\t\t\tTextColor3 = Color3.fromRGB(255, 255, 255),\n\t\t\tTextSize = 10.5,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tBorderSizePixel = 0,\n\t\t\tAutoButtonColor = false,\n\t\t\tParent = card,\n\t\t}, { corner(6) })\n\t\trecToggleBtn.MouseButton1Click:Connect(function()\n\t\t\tif isRecordingAnim then\n\t\t\t\tstopRecordingAnim()\n\t\t\telse\n\t\t\t\tstartRecordingAnim()\n\t\t\tend\n\t\tend)\n\n\t\trecNameInput = new("TextBox", {\n\t\t\tSize = UDim2.new(1, 0, 0, 26),\n\t\t\tPosition = UDim2.new(0, 0, 0, 154),\n\t\t\tBackgroundColor3 = T.surface3,\n\t\t\tTextColor3 = T.text1,\n\t\t\tPlaceholderText = "Animation name (e.g. MyRecordedAnim)...",\n\t\t\tPlaceholderColor3 = T.text3,\n\t\t\tTextSize = 9,\n\t\t\tFont = Enum.Font.BuilderSansMedium,\n\t\t\tText = "",\n\t\t\tClearTextOnFocus = false,\n\t\t\tBorderSizePixel = 0,\n\t\t\tParent = card,\n\t\t}, { corner(5), pad(0, 8, 0, 8) })\n\t\tstroke(T.line, 1, 0.5).Parent = recNameInput\n\n\t\tlocal actionsRow = new("Frame", {\n\t\t\tSize = UDim2.new(1, 0, 0, 28),\n\t\t\tPosition = UDim2.new(0, 0, 0, 188),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tParent = card,\n\t\t})\n\n\t\trecPrevBtn = new("TextButton", {\n\t\t\tSize = UDim2.new(0.48, -4, 1, 0),\n\t\t\tPosition = UDim2.new(0, 0, 0, 0),\n\t\t\tBackgroundColor3 = T.surface3,\n\t\t\tText = "Preview",\n\t\t\tTextColor3 = T.accent2,\n\t\t\tTextSize = 9,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tBorderSizePixel = 0,\n\t\t\tAutoButtonColor = false,\n\t\t\tVisible = (#recordedFrames > 0),\n\t\t\tParent = actionsRow,\n\t\t}, { corner(5) })\n\t\tstroke(T.accent2, 1, 0.4).Parent = recPrevBtn\n\n\t\trecPrevBtn.MouseButton1Click:Connect(function()\n\t\t\tif #recordedFrames == 0 then return end\n\t\t\tif onyxAPI.is_animation_playing and onyxAPI.is_animation_playing() and onyx.animation.state.current_url\n\t\t\t\tand tostring(onyx.animation.state.current_url):sub(1, 8) == "return {" and onyx.animation.state.current_url:find("Time = ", 1, true) then\n\t\t\t\tonyxAPI.stop_animation()\n\t\t\t\trecordStatusLabel.Text = "Preview stopped"\n\t\t\t\trecordStatusLabel.TextColor3 = T.text1\n\t\t\t\treturn\n\t\t\tend\n\t\t\tif not (onyxAPI.is_reanimated and onyxAPI.is_reanimated()) then\n\t\t\t\trecordStatusLabel.Text = "Enable