\t\tTextColor3 = Color3.fromRGB(15, 15, 20),\n\t\t\tTextSize = 9,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tZIndex = 11,\n\t\t\tParent = saveInner,\n\t\t})\n\t\tlocal function setSaveLabel(t, withIcon)\n\t\t\tsaveLabel.Text = t\n\t\t\tsaveIcon.Visible = withIcon\n\t\tend\n\t\trecSaveBtn.MouseButton1Click:Connect(function()\n\t\t\tif #recordedFrames == 0 then\n\t\t\t\trecordStatusLabel.Text = "No frames to save!"\n\t\t\t\trecordStatusLabel.TextColor3 = T.danger\n\t\t\t\treturn\n\t\t\tend\n\t\t\tlocal name = (recNameInput.Text ~= "") and recNameInput.Text or ("Recorded_" .. tostring(os.date("%H%M%S")))\n\t\t\tlocal sanitized = name:gsub("[^%w%s%-_]", ""):match("^%s*(.-)%s*$")\n\t\t\tif not sanitized or sanitized == "" then sanitized = "Recorded_" .. tostring(tick()):sub(-4) end\n\t\t\tlocal animCode = buildRecordedLua(recordedFrames)\n\t\t\ttransformCache[sanitized] = animCode\n\t\t\tif animationQueue then animationQueue[sanitized] = animCode end\n\t\t\tpcall(function()\n\t\t\t\tif not isfolder(customsFolderPath) then makefolder(customsFolderPath) end\n\t\t\t\tif writefile then\n\t\t\t\t\twritefile(customsFolderPath .. "/" .. sanitized .. ".lua", animCode)\n\t\t\t\tend\n\t\t\tend)\n\t\t\trecordStatusLabel.Text = "Saved: " .. sanitized .. ".lua"\n\t\t\trecordStatusLabel.TextColor3 = Color3.fromRGB(80, 220, 120)\n\t\t\tsetSaveLabel("Saved!", false)\n\t\t\ttask.delay(1.5, function()\n\t\t\t\tsetSaveLabel("Save to Customs", true)\n\t\t\tend)\n\t\t\tinitializeGui()\n\t\t\tif characterModel4 == "custom" then pcall(loadGUI) end\n\t\tend)\n\tend\n\trefreshRecordPanel()\n\tend\n\tdo\n\t-- \u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{25