\n\t\tif modalState.callback then modalState.callback(name) end\n\tend\n\n\tlocal function ensureModalRows()\n\t\tif not noneRow then\n\t\t\tnoneRow = new("Frame", {\n\t\t\t\tSize = UDim2.new(1, 0, 0, 28),\n\t\t\t\tBackgroundColor3 = Color3.fromRGB(35, 20, 25),\n\t\t\t\tBorderSizePixel = 0,\n\t\t\t\tLayoutOrder = -1,\n\t\t\t\tParent = modalScroll,\n\t\t\t}, { corner(6), pad(0, 8, 0, 8) })\n\t\t\tstroke(T.danger, 1, 0.7).Parent = noneRow\n\t\t\tlocal noneBtn = new("TextButton", {\n\t\t\t\tSize = UDim2.fromScale(1, 1),\n\t\t\t\tBackgroundTransparency = 1,\n\t\t\t\tText = "None (Remove)",\n\t\t\t\tTextColor3 = T.danger,\n\t\t\t\tTextSize = 10,\n\t\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\t\t\tParent = noneRow,\n\t\t\t})\n\t\t\tnoneBtn.MouseButton1Click:Connect(function()\n\t\t\t\tlocal stateName = modalState.name\n\t\t\t\tif not stateName then return end\n\t\t\t\tstateAnimations[stateName] = nil\n\t\t\t\tstateAnimations[tostring(stateName):lower()] = nil\n\t\t\t\tpcall(saveStateAnimations)\n\t\t\t\tselectModal.Visible = false\n\t\t\t\tif isInitialized and animationFolder then pcall(stateCheckFunction) end\n\t\t\t\tif modalState.callback then modalState.callback("None (Click to select)") end\n\t\t\tend)\n\t\tend\n\n\t\tlocal allAnims = getAllAnimNames and getAllAnimNames() or {}\n\t\tlocal sig = table.concat(allAnims, "\\0")\n\t\tif sig == modalRowsSig then return end\n\t\tmodalRowsSig = sig\n\t\tmodalBuildToken += 1\n\t\tlocal mine = modalBuildToken\n\t\tfor _, r in pairs(modalRows) do pcall(function() r:Destroy() end) end\n\t\tmodalRows = {}\n\t\ttask.spawn(function()\n\t\t\tfor i, name in ipairs(allAnims) do\n\t\t\t\tif mine ~= modalBuildToken then return end\n\t\t\t\tlocal row = new("Frame", {\n\t\t\t\t\tSize = UDim2.new(1, 0, 0, 28),\n\t\t\t\t\tBackgroundColor3 = T.surface2,\n\t\t\t\t\tBorderSizePixel = 0,\n\t\t\t\t\tLayoutOrder = i,\n\t\t\t\t\tParent = modalScroll,\n\t\t\t\t}, { corner(6), pad(0, 8, 0, 8) })\n\